            label: "nums",
            items: nums.map((v, i) => ({ v, cls: i === cur ? "a" : i >= ql && i <= qr ? "e" : "" })),
            ptrs: { i: cur >= 0 ? cur : null },
          },
          {
            t: "array",
            label: "pre（pre[i] 是前 i 个数的和）",
            items: pre.map((v, i) => ({ v: v === null ? "" : v, cls: use.includes(i) ? "a" : v === null ? "" : "c" })),
            ptrs: opts.prePtrs || {},
