class Solution:
    def corpFlightBookings(self, bookings: List[List[int]], n: int) -> List[int]:
        diff = [0] * (n + 1)                    # diff[i] = ans[i] - ans[i-1]
        for first, last, seats in bookings:
            diff[first - 1] += seats            # 从 first 开始多了 seats
            diff[last] -= seats                 # 过了 last 又少了 seats
        ans = [0] * n
        cur = 0
        for i in range(n):
            cur += diff[i]                      # 前缀和还原出每个位置的值
            ans[i] = cur
        return ans

