                ...(prevMap[i] !== undefined ? { prev: prevMap[i] } : {}),
                cls: hot.includes(i) ? "a" : i >= lo && i <= hi ? "e" : "",
              })),
              ptrs: opts.diffPtrs || {},
            },
            {
              t: "array",
              label: "ans（航班 1 到 n）",
              items: ans.map((v, i) => ({ v: v === null ? "" : v, cls: i === at ? "a" : v === null ? "" : "c" })),
              ptrs: at >= 0 ? { i: at } : {},
              feeds: opts.feeds || [],
            },
          ];
        };
