        });
        let prevBook = "—";
        for (const [f, l, s] of a.bookings) {
          const oldF = diff[f - 1], oldL = diff[l];
          diff[f - 1] += s;
          diff[l] -= s;
          hot = [f - 1, l];
          lo = f - 1;
          hi = l - 1;
