            feeds: i > 0 ? [{ from: i - 1, to: i, win: true, label: delta }] : [],
          }), {
            at: "sum",
            facts: [
              ["阶段", "前缀和还原", prevStage],
              ["下标 i", i, i === 0 ? "—" : i - 1],
              ["cur", cur, prevCur],
              [`ans[${i}]`, cur],
            ],
          });
          prevStage = "前缀和还原";
        }
        at = -1; hot = [];
        snap("完成", `答案是 [${ans.join(", ")}]。`, view(), {
          at: "done",
          kind: "ok",
          ans: ans.slice(),
          facts: [["最终结果", `[${ans.join(", ")}]`]],
